using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Encodings.Web;
namespace SmartTrainingPresenter;

public static class J {
    public static readonly JsonSerializerOptions Options=new(){WriteIndented=true,Encoder=JavaScriptEncoder.UnsafeRelaxedJsonEscaping};
    public static JsonNode Load(string p){if(new FileInfo(p).Length>30_000_000)throw new InvalidDataException("ملف JSON كبير");return JsonNode.Parse(File.ReadAllText(p))??throw new InvalidDataException("JSON فارغ");}
    public static string Str(JsonNode n,string key)=>n[key]?.GetValue<string>()??"";
    public static double Num(JsonNode n,string key)=>n[key]==null?0:double.Parse(n[key]!.ToJsonString(),System.Globalization.CultureInfo.InvariantCulture);
    public static int Int(JsonNode n,string key)=>(int)Num(n,key);
    public static bool Bool(JsonNode n,string key)=>n[key]?.GetValue<bool>()??false;
    public static string Hash(string p){using var f=File.OpenRead(p);return Convert.ToHexStringLower(SHA256.HashData(f));}
    public static void Atomic(string path,JsonNode n){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);var temp=path+"."+Guid.NewGuid()+".tmp";try{using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var b=Encoding.UTF8.GetBytes(n.ToJsonString(Options));f.Write(b);f.Flush(true);}if(File.Exists(path))File.Replace(temp,path,path+".bak",true);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
    public static string Safe(string root,string relative){if(string.IsNullOrEmpty(relative)||relative.Contains('\\')||relative.Contains(':')||Path.IsPathRooted(relative)||relative.Split('/').Contains(".."))throw new InvalidDataException("مسار غير آمن");root=Path.GetFullPath(root);var p=root;foreach(var part in relative.Split('/')){p=Path.Combine(p,part);if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("روابط الملفات غير مسموحة");}p=Path.GetFullPath(p);if(!p.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("مسار خارج الحزمة");return p;}
    public static JsonNode Semantic(JsonNode p){var q=p.DeepClone();foreach(var m in q["materials"]!.AsArray()){m!.AsObject().Remove("path");m.AsObject().Remove("renderedPath");}return q;}
    public static string SemanticHash(JsonNode p){JsonNode? Sort(JsonNode? n)=>n is JsonObject o?new JsonObject(o.OrderBy(k=>k.Key,StringComparer.Ordinal).Select(k=>new KeyValuePair<string,JsonNode?>(k.Key,Sort(k.Value)))):n is JsonArray a?new JsonArray(a.Select(Sort).ToArray()):n?.DeepClone();var s=Sort(Semantic(p))!.ToJsonString(new JsonSerializerOptions{Encoder=JavaScriptEncoder.UnsafeRelaxedJsonEscaping});return Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(s)));}
}
public sealed class Project {
    public JsonNode Node;public string Pathname;
    public Dictionary<string,Countdown> Live=[];
    public Project(string path){Pathname=path;try{Node=J.Load(path);Validate(Node);}catch when(File.Exists(path+".bak")){Node=J.Load(path+".bak");Validate(Node);}
        // Persisted monotonic anchors are never resumed, even following recovery.
        foreach(var t in Node["timers"]!.AsObject().Select(x=>x.Value!).Append(Node["freeTimer"]!)){t["running"]=false;t.AsObject().Remove("anchor");}}
    public JsonArray Activities=>Node["activities"]!.AsArray();public JsonArray Materials=>Node["materials"]!.AsArray();
    public static void Validate(JsonNode n){if(J.Int(n,"version")!=1||J.Int(n,"currentPage")<0)throw new InvalidDataException("إصدار/صفحة غير صالح");var mats=n["materials"]!.AsArray();var acts=n["activities"]!.AsArray();if(mats.Count>=2000||acts.Count>=20000)throw new InvalidDataException("تجاوز حدود الحقيبة");foreach(var arr in new[]{mats,acts})if(arr.Select(x=>J.Str(x!,"id")).Distinct().Count()!=arr.Count)throw new InvalidDataException("معرّف مكرر");foreach(var a in acts)foreach(var key in new[]{"duration","original"})if(J.Num(a!,key)<=0||!double.IsFinite(J.Num(a!,key)))throw new InvalidDataException("مدة غير صالحة");var pref=n["preferences"]!;if(J.Num(pref,"volume")<0||J.Num(pref,"volume")>1||J.Num(pref,"noticeSeconds")<1||J.Num(pref,"noticeSeconds")>60)throw new InvalidDataException("تفضيلات غير صالحة");foreach(var t in n["timers"]!.AsObject().Select(x=>x.Value!).Append(n["freeTimer"]!)){foreach(var key in new[]{"original","adjusted","extensions","elapsed","previous"})if(!double.IsFinite(J.Num(t,key)))throw new InvalidDataException("مؤقت غير صالح");if(J.Num(t,"original")<=0||J.Num(t,"adjusted")<=0||J.Num(t,"extensions")<0||J.Num(t,"elapsed")<0)throw new InvalidDataException("مؤقت غير صالح");}}
    public Countdown Timer(string id){if(!Live.TryGetValue(id,out var t)){var n=id=="free"?Node["freeTimer"]:Node["timers"]?[id];var a=Activities.FirstOrDefault(x=>J.Str(x!,"id")==id);Live[id]=t=n!=null?Countdown.Read(n):new Countdown(a==null?600:J.Num(a,"duration"));}return t;}
    public JsonNode Snapshot(){var q=Node.DeepClone();var now=Clock.Now;foreach(var(id,t)in Live){var c=t.Checkpoint(now);if(id=="free")q["freeTimer"]=c.Write(q["freeTimer"]);else q["timers"]![id]=c.Write(q["timers"]?[id]);}return q;}
    public void Save(string? path=null){var q=Snapshot();Validate(q);J.Atomic(path??Pathname,q);}
    public void Edit(JsonNode a,string key,JsonNode? value){if(!JsonNode.DeepEquals(a[key],value)){a[key]=value?.DeepClone();a["approved"]=false;}}
    public void Delete(string id){var a=Activities.First(x=>J.Str(x!,"id")==id);Activities.Remove(a);Node["timers"]!.AsObject().Remove(id);Live.Remove(id);if(J.Str(Node,"currentActivity")==id)Node.AsObject().Remove("currentActivity");}
}
public static class Library {
    public static string SourcePath(string root,string relative){var expected=J.Safe(root,relative);if(File.Exists(expected))return expected;var directory=Path.GetDirectoryName(expected)!;if(!Directory.Exists(directory))throw new FileNotFoundException("مصدر مفقود",expected);var candidates=Directory.EnumerateFiles(directory).Where(x=>Path.GetFileName(x).Normalize(NormalizationForm.FormC)==Path.GetFileName(expected).Normalize(NormalizationForm.FormC)).ToArray();if(candidates.Length!=1)throw new InvalidDataException("اسم Unicode مفقود أو ملتبس");var resolved=J.Safe(root,Path.GetRelativePath(root,candidates[0]).Replace('\\','/'));return resolved;}
    public static JsonNode Verify(string source){var manifest=J.Load(Path.Combine(source,"manifest.json"));if(J.Str(manifest,"format")!="stp-portable-library"||J.Int(manifest,"version")!=1)throw new InvalidDataException("حزمة مكتبة غير مدعومة");var files=manifest["files_sha256"]!.AsObject();var actual=Directory.EnumerateFiles(source,"*",SearchOption.AllDirectories).Where(x=>Path.GetFileName(x)!="manifest.json").Select(x=>Path.GetRelativePath(source,x).Replace('\\','/')).ToHashSet(StringComparer.Ordinal);if(actual.Count!=actual.Select(x=>x.Normalize(NormalizationForm.FormC)).Distinct().Count()||!actual.Select(x=>x.Normalize(NormalizationForm.FormC)).ToHashSet().SetEquals(files.Select(x=>x.Key.Normalize(NormalizationForm.FormC))))throw new InvalidDataException("ملفات زائدة أو ناقصة؛ تحقق من أسماء Unicode");foreach(var f in files){var p=SourcePath(source,f.Key);if(J.Hash(p)!=f.Value!.GetValue<string>())throw new InvalidDataException("بصمة غير مطابقة: "+f.Key);}var index=J.Load(Path.Combine(source,"Library/index.json"));int items=0,approvals=0,evidence=0;foreach(var bag in index["bags"]!.AsArray()){var p=J.Load(J.Safe(source,"Library/Projects/"+J.Str(bag!,"id")+".stpresenter"));Project.Validate(p);if(J.SemanticHash(p)!=J.Str(manifest["project_semantic_sha256"]!,"Library/Projects/"+J.Str(bag!,"id")+".stpresenter"))throw new InvalidDataException("بصمة قرارات الحقيبة غير مطابقة");if(J.Str(p,"libraryBagID")!=J.Str(bag!,"id"))throw new InvalidDataException("هوية الحقيبة");var mids=p["materials"]!.AsArray().ToDictionary(x=>J.Str(x!,"id"));foreach(var m in mids.Values){if(J.Hash(SourcePath(source,J.Str(m!,"path")))!=J.Str(m!,"hash"))throw new InvalidDataException("مصدر تغير");if(m!["renderedPath"]!=null&&!File.Exists(SourcePath(source,J.Str(m,"renderedPath"))))throw new FileNotFoundException("نسخة العرض مفقودة");}foreach(var a in p["activities"]!.AsArray()){items++;if(J.Bool(a!,"approved"))approvals++;foreach(var e in a!["evidence"]!.AsArray()){evidence++;if(!mids.TryGetValue(J.Str(e!,"fileID"),out var mat)||J.Int(e!,"page")<1||J.Int(e!,"page")>J.Int(mat!,"pages"))throw new InvalidDataException("إحالة/صفحة غير صالحة");}}}if(items!=J.Int(manifest["counts"]!,"time_items")||approvals!=J.Int(manifest["counts"]!,"approvals")||evidence!=J.Int(manifest["counts"]!,"evidence")||index["bags"]!.AsArray().Count!=J.Int(manifest["counts"]!,"bags"))throw new InvalidDataException("أعداد غير مطابقة");return manifest;}
    public static void Restore(string source,string target){Verify(source);target=Path.GetFullPath(target);if(Directory.Exists(target)&&Directory.EnumerateFileSystemEntries(target).Any()||File.Exists(target))throw new IOException("الوجهة يجب أن تكون جديدة أو فارغة");var staging=target+".import-"+Guid.NewGuid();Directory.CreateDirectory(staging);try{var mf=J.Load(Path.Combine(source,"manifest.json"));foreach(var f in mf["files_sha256"]!.AsObject()){var dest=J.Safe(staging,f.Key);Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(SourcePath(source,f.Key),dest);}
        foreach(var f in mf["project_semantic_sha256"]!.AsObject()){var p=J.Load(J.Safe(staging,f.Key));var before=J.Semantic(p);foreach(var m in p["materials"]!.AsArray())foreach(var key in new[]{"path","renderedPath"})if(m![key]!=null)m[key]=J.Safe(target,J.Str(m,key));if(!JsonNode.DeepEquals(before,J.Semantic(p)))throw new InvalidDataException("تغير قرار");J.Atomic(J.Safe(staging,f.Key),p);}
        var index=J.Load(Path.Combine(staging,"Library/index.json"));index["root"]=target;J.Atomic(Path.Combine(staging,"Library/index.json"),index);
        // Atomic writer backups inside staging are redundant; never copy originals back.
        foreach(var b in Directory.EnumerateFiles(staging,"*.bak",SearchOption.AllDirectories))File.Delete(b);
        if(Directory.Exists(target))Directory.Delete(target);Directory.Move(staging,target);
    }catch{if(Directory.Exists(staging))Directory.Delete(staging,true);throw;}}
    public static Project LoadBag(string root,string id){var p=new Project(J.Safe(root,"Library/Projects/"+id+".stpresenter"));foreach(var m in p.Materials){if(!File.Exists(J.Str(m!,"path")))throw new FileNotFoundException("مصدر مفقود: "+J.Str(m!,"path"));if(J.Hash(J.Str(m!,"path"))!=J.Str(m!,"hash"))throw new InvalidDataException("تغير المصدر");}return p;}
    public static Project LoadBagPackage(string root){var p=new Project(Path.Combine(root,"project.json"));foreach(var m in p.Materials)foreach(var key in new[]{"path","renderedPath"})if(m![key]!=null)m[key]=J.Safe(root,J.Str(m,key));return p;}
    public static void ExportBag(Project project,string target){if(Directory.Exists(target)||File.Exists(target))throw new IOException("اختر وجهة جديدة");var staging=target+".export-"+Guid.NewGuid();Directory.CreateDirectory(staging);try{var p=project.Snapshot();for(int i=0;i<p["materials"]!.AsArray().Count;i++){var m=p["materials"]![i]!;var old=J.Str(m,"path");var rel=$"Materials/{i}/"+Path.GetFileName(old);var dest=J.Safe(staging,rel);Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(old,dest);if(J.Hash(dest)!=J.Str(m,"hash"))throw new InvalidDataException("مصدر تغير");m["path"]=rel;if(m["renderedPath"]!=null){var rp=J.Str(m,"renderedPath");if(rp==old)m["renderedPath"]=rel;else{var r=$"Previews/{i}.pdf";Directory.CreateDirectory(Path.Combine(staging,"Previews"));File.Copy(rp,J.Safe(staging,r));m["renderedPath"]=r;}}}J.Atomic(Path.Combine(staging,"project.json"),p);Directory.Move(staging,target);}catch{if(Directory.Exists(staging))Directory.Delete(staging,true);throw;}}
}
